package com.jiugeng.erp.watch;
import static com.jiugeng.erp.watch.WatchTypes.*;
import com.jiugeng.erp.iam.*;import com.jiugeng.erp.selection.SelectionCandidateGateway;import com.jiugeng.erp.watch.collector.*;import java.net.URI;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Instant;import java.util.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service class WatchService{
 private final WatchRepository repository;private final SelectionCandidateGateway candidates;private final AuditTrail audit;private final ManualSnapshotCollectorAdapter adapter=new ManualSnapshotCollectorAdapter();private final SnapshotIntegrityEvaluator integrityEvaluator=new SnapshotIntegrityEvaluator();private final BaselineProtector protector=new BaselineProtector();private final DiffDeduplicator deduplicator=new DiffDeduplicator();
 WatchService(WatchRepository repository,SelectionCandidateGateway candidates,AuditTrail audit){this.repository=repository;this.candidates=candidates;this.audit=audit;}
 @Transactional(readOnly=true) List<StoreView> stores(){return repository.stores();}
 @Transactional Optional<StoreView> restoreStore(String key,AuthenticatedActor actor){return repository.removedId(key).map(id->{repository.restore(id);audit.record(operation(actor,"WATCH_STORE_RESTORE",id,null,null,"重新添加监控店铺"));return store(id);});}
 @Transactional(readOnly=true) List<EventView> events(){return repository.events();}
 @Transactional StoreView createStore(String key,String name,String sourceUrl,AuthenticatedActor actor){key=required(key,"店铺标识",100);name=required(name,"店铺名称",200);validateHttps(sourceUrl);String id=UUID.randomUUID().toString();try{repository.insertStore(id,key,name,sourceUrl.trim(),actor.userId());}catch(DataIntegrityViolationException e){throw conflict("WATCH_STORE_EXISTS","店铺标识已存在（忽略大小写）");}StoreView created=store(id);audit.record(operation(actor,"WATCH_STORE_CREATE",id,null,Map.of("storeKey",key,"storeName",name,"sourceUrl","[REDACTED_HTTPS_URL]"),"登记获批监控来源"));return created;}
 @Transactional RunResult run(String storeId,String requestId,RunStatus status,int itemCount,int pageCount,boolean pagesComplete,List<String> rawAsins,AuthenticatedActor actor){
  repository.lockStore(storeId);StoreView current=store(storeId);if(!current.status().equals("ACTIVE"))throw conflict("WATCH_PAUSED","店铺已暂停");Set<String> everSeen=repository.previouslySeen(storeId);requestId=required(requestId,"请求标识",100);List<String> source=rawAsins==null?List.of():rawAsins;String payload=storeId+"|"+status+"|"+itemCount+"|"+pageCount+"|"+pagesComplete+"|"+String.join(",",source);String payloadHash=sha(payload);
  var replay=repository.runByRequest(requestId);if(replay.isPresent()){if(!replay.get().storeId().equals(storeId)||!replay.get().payloadHash().equals(payloadHash))throw conflict("WATCH_REQUEST_CONFLICT","相同 requestId 的载荷不同");RunView run=repository.run(replay.get().id());return new RunResult(store(storeId),repository.eventsForRun(run.id()),false,run,true);}
  String runId=UUID.randomUUID().toString();CollectorRequest request=new CollectorRequest(runId,current.storeKey(),"ATVPDKIKX0DER",new SourceApproval(SourceApproval.Status.APPROVED,SourceApproval.SourceClass.MANUAL_IMPORT,false,Instant.now()));CollectorResult collected;
  try{collected=adapter.collectManual(request,new ManualSnapshot(status==RunStatus.SUCCEEDED?SnapshotManifest.RunStatus.SUCCEEDED:SnapshotManifest.RunStatus.FAILED,itemCount,pageCount,pagesComplete,source));}catch(IllegalArgumentException e){throw invalid("WATCH_SNAPSHOT_INVALID",e.getMessage());}
  IntegrityResult integrity=integrityEvaluator.evaluate(collected.manifest(),collected.asins());if(status==RunStatus.SUCCEEDED&&collected.asins().isEmpty())integrity=new IntegrityResult(IntegrityResult.Status.INCOMPLETE,List.of(new IntegrityResult.Check("NON_EMPTY",false,"0")));
  BaselineDecision decision=protector.decide(runId,current.baselineRunId(),integrity);Instant completed=collected.manifest().completedAt();repository.insertRun(runId,storeId,requestId,payloadHash,status.name(),itemCount,collected.asins().size(),pageCount,pagesComplete,collected.manifest().contentSha256(),integrity.status().name(),decision.decision().name(),decision.reasonCode(),completed,actor.userId());repository.insertSnapshot(runId,collected.asins());
  if(decision.decision()==BaselineDecision.Decision.PROMOTED){Set<String> before=repository.baseline(storeId);if(current.baselineRunId()!=null){for(String asin:collected.asins()){if(before.contains(asin)||everSeen.contains(asin))continue;String eventKey=deduplicator.eventKey(current.storeKey(),"ATVPDKIKX0DER",asin);try{repository.insertEvent(UUID.randomUUID().toString(),eventKey,storeId,runId,asin,"监控新品 "+asin,completed);}catch(DataIntegrityViolationException duplicate){/* same store/ASIN event remains singular */}}}repository.promoteBaseline(storeId,runId,collected.asins());}
  RunView saved=repository.run(runId);audit.record(operation(actor,"WATCH_RUN_SUBMIT",runId,null,Map.of("storeId",storeId,"status",status.name(),"integrity",integrity.status().name(),"decision",decision.decision().name(),"asinCount",collected.asins().size()),"人工快照完整性验收"));return new RunResult(store(storeId),repository.eventsForRun(runId),decision.decision()==BaselineDecision.Decision.PROMOTED,saved,false);
 }
 @Transactional Confirmation confirm(String eventId,AuthenticatedActor actor){repository.lockEvent(eventId);EventView before=event(eventId);if(before.status().equals("IGNORED"))throw conflict("WATCH_IGNORED","请先恢复忽略事件");if(before.candidateId()!=null)return new Confirmation(before,new CandidateRef(before.candidateId()),true);StoreView store=store(before.storeId());var confirmation=candidates.confirmWatchCandidate(before.asin(),before.title(),store.storeName(),before.detectedAt(),before.sourceRunId(),before.id(),actor);repository.confirm(eventId,confirmation.candidateId(),actor.userId());EventView after=event(eventId);audit.record(operation(actor,"WATCH_EVENT_CONFIRM",eventId,Map.of("status",before.status()),Map.of("status",after.status(),"candidateId",confirmation.candidateId()),"确认上新事件进入候选池"));return new Confirmation(after,new CandidateRef(confirmation.candidateId()),false);}
 private StoreView store(String id){return repository.store(id).orElseThrow(()->new WatchException(404,"WATCH_STORE_NOT_FOUND","监控店铺不存在："+id));}private EventView event(String id){return repository.event(id).orElseThrow(()->new WatchException(404,"WATCH_EVENT_NOT_FOUND","监控事件不存在："+id));}
 private void validateHttps(String value){try{URI u=URI.create(required(value,"来源链接",1000));if(!"https".equalsIgnoreCase(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null)throw new IllegalArgumentException();}catch(IllegalArgumentException e){throw invalid("WATCH_SOURCE_URL_INVALID","来源链接必须是无 userinfo 的 HTTPS URL");}}
 private String required(String v,String label,int max){if(v==null||v.trim().isEmpty()||v.trim().length()>max)throw invalid("WATCH_FIELD_INVALID",label+"不能为空且长度不能超过 "+max);return v.trim();}private String sha(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private WatchException invalid(String c,String m){return new WatchException(400,c,m);}private WatchException conflict(String c,String m){return new WatchException(409,c,m);}private AuditTrail.BusinessOperation operation(AuthenticatedActor a,String action,String id,Map<String,?> before,Map<String,?> after,String detail){return new AuditTrail.BusinessOperation(a.userId(),a.loginName(),a.displayName(),action,"WATCH",id,true,before,after,detail);}
}
